if(current_user()['role']!=='Admin')throw new Exception('Admin access required.');echo '<div class="page-head"><div><h1>Backups & Restore Tests</h1><p>Private database, application and attachment backups. Restore tests use a separate disposable database.</p></div></div><div class="card"><p>Last successful backup: <b>'.e(setting('backup_last_success','None')).'</b></p><p>Daily automatic backup: '.(setting('backup_auto_enabled','1')==='1'?'Enabled':'Disabled').'. A first Admin visit catches up a missed daily backup. Install the supplied Windows schedule for daily runs while signed in; MySQL must be running.</p><p>Storage: '.e(backup_root()).'. Download and keep a second copy off this computer.</p><div class="modal-actions"><form method="post" action="actions.php"><input type="hidden" name="action" value="backup_create"><input type="hidden" name="return" value="backups"><button class="btn primary">Back Up Now</button></form><form method="post" action="actions.php"><input type="hidden" name="action" value="backup_settings"><input type="hidden" name="return" value="backups"><label><input type="checkbox" name="enabled" value="1" '.(setting('backup_auto_enabled','1')==='1'?'checked':'').'> Enable daily automatic backup</label><button class="btn secondary">Save</button></form></div></div><div class="card table-wrap"><table class="table"><tr><th>Date / Reference</th><th>Status</th><th>Restore Test</th><th>Details</th><th>Actions</th></tr>';
$offset=max(0,(int)($_GET['offset']??0));$total=(int)db()->query('SELECT COUNT(*) FROM process_backups')->fetchColumn();foreach(db()->query('SELECT * FROM process_backups ORDER BY id DESC LIMIT 50 OFFSET '.$offset) as $b){echo '<tr><td>'.e($b['created_at']).'<br>'.e($b['backup_ref']).'</td><td>'.e($b['status']).'</td><td>'.e($b['restore_test_status']??'Not tested').'<br>'.e($b['restore_test_at']??'').'</td><td>'.e($b['error_text']??'').'</td><td>';if($b['status']==='Complete')echo '<a class="btn ghost" href="backup_download.php?id='.$b['id'].'">Download</a><form method="post" action="actions.php" data-confirm="Verify all backup files and restore the database into an isolated temporary database? Live inventory stays unchanged."><input type="hidden" name="action" value="backup_verify"><input type="hidden" name="return" value="backups"><input type="hidden" name="backup_id" value="'.$b['id'].'"><button class="btn secondary">Test Restore</button></form>';echo '</td></tr>';}echo '</table><div class="modal-actions"><span>'.($total?($offset+1).'–'.min($total,$offset+50).' of '.$total:'No backups yet').'</span>';echo rs8_pagination($total,$offset,50,array_replace($_GET,['page'=>'backups']));echo '</div></div>';
